// JDK 17+, standard HTTP, Nimbus JOSE/JWT. Never ship AppSecret.
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.nimbusds.jose.*;
import com.nimbusds.jose.crypto.RSASSAVerifier;
import com.nimbusds.jose.jwk.*;
import com.nimbusds.jwt.*;
import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.*;
import java.security.spec.*;
import java.time.*;
import java.util.*;

public final class LicenseClient {
 static final String APP_ID="@@APP_ID@@",ISSUER="urn:yunnuo:licensing:v2";
 static final ObjectMapper JSON=new ObjectMapper();
 static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
 static final String BASE=env("YN_LICENSE_URL","@@LICENSE_URL@@").replaceAll("/$","");
 static final Path STATE=Path.of(env("YN_STATE_DIR","./license-state"),APP_ID);
 static final String KIND=env("YN_BINDING_TYPE","@@DEFAULT_BINDING@@"),FORM=env("YN_FORM","@@DEFAULT_FORM@@");
 static PrivateKey privateKey;static String publicText,publicHash,bindingHash;static ObjectNode binding;
 static String env(String name,String fallback){String v=System.getenv(name);return v==null||v.isEmpty()?fallback:v;}
 static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}
 static String sha(byte[] raw)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw));}
 static void permissions(Path path,String value)throws IOException{try{Files.setPosixFilePermissions(path,PosixFilePermissions.fromString(value));}catch(UnsupportedOperationException ignored){/* On Windows protect this directory with the application's user ACL. */}}
 static void save(String name,JsonNode data)throws Exception{Path file=Files.createTempFile(STATE,".save-",".json");try{permissions(file,"rw-------");Files.write(file,JSON.writeValueAsBytes(data));try{Files.move(file,STATE.resolve(name),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(file,STATE.resolve(name),StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(file);}}
 static ObjectNode load(String name)throws Exception{Path file=STATE.resolve(name);if(!Files.exists(file))return JSON.createObjectNode();JsonNode node=JSON.readTree(Files.readAllBytes(file));if(!node.isObject())throw new SecurityException("Invalid local state");return (ObjectNode)node;}

 static void discardTokens()throws Exception{ObjectNode cached=load("cache.json"),identity=JSON.createObjectNode();for(String key:List.of("activation_id","license_id")){if(!cached.path(key).asText().isEmpty())identity.put(key,cached.path(key).asText());}if(cached.path("highwater").asLong()>0)identity.put("highwater",cached.path("highwater").asLong());save("cache.json",identity);}
 static void initialize()throws Exception{Files.createDirectories(STATE);permissions(STATE,"rwx------");Path keyFile=STATE.resolve("installation.pk8"),pubFile=STATE.resolve("installation.spki");
  if(!Files.exists(keyFile)){KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();try{Files.createFile(keyFile);permissions(keyFile,"rw-------");Files.write(keyFile,pair.getPrivate().getEncoded());Files.write(pubFile,pair.getPublic().getEncoded(),StandardOpenOption.CREATE_NEW);}catch(FileAlreadyExistsException e){throw new IOException("Concurrent identity initialization; retry after the other process completes",e);}}
  KeyFactory factory=KeyFactory.getInstance("Ed25519");privateKey=factory.generatePrivate(new PKCS8EncodedKeySpec(Files.readAllBytes(keyFile)));PublicKey pub=factory.generatePublic(new X509EncodedKeySpec(Files.readAllBytes(pubFile)));byte[] encoded=pub.getEncoded(),raw=Arrays.copyOfRange(encoded,encoded.length-32,encoded.length);publicText=Base64.getUrlEncoder().withoutPadding().encodeToString(raw);publicHash=sha(raw);
  String value=env("YN_BINDING_VALUE",KIND.equals("installation")?publicHash:"");switch(KIND){case "seat":value="seat";break;case "domain":URI uri=URI.create(value.contains("://")?value:"https://"+value);String host=uri.getHost();if(host==null){host=uri.getRawAuthority();if(host==null||host.contains("@"))throw new IllegalArgumentException("Invalid domain");int colon=host.lastIndexOf(':');if(colon>=0)host=host.substring(0,colon);}value=IDN.toASCII(host.toLowerCase(Locale.ROOT).replaceAll("\\.$",""));break;
   case "ip":if(!value.matches("[0-9a-fA-F:.]+"))throw new IllegalArgumentException("IP must be a literal address");value=InetAddress.getByName(value).getHostAddress();break;
   case "machine_id":String source=System.getenv("YN_HOST_FINGERPRINT_FILE");if(source!=null)value=Files.readString(Path.of(source)).trim();else{if(FORM.equals("container")||FORM.equals("cluster")||Files.exists(Path.of("/.dockerenv"))||System.getenv("KUBERNETES_SERVICE_HOST")!=null)throw new SecurityException("Container machine fingerprint forbidden: use seat or a mounted host SHA-256 fingerprint and persistent state volume");if(value.isEmpty()){for(String candidate:List.of("/sys/class/dmi/id/product_uuid","/etc/machine-id")){try{String hardware=Files.readString(Path.of(candidate)).trim();if(!hardware.isEmpty()){value=sha(bytes(hardware));break;}}catch(IOException ignored){}}}}value=value.toLowerCase(Locale.ROOT);if(!value.matches("[a-f0-9]{64}"))throw new SecurityException("Real SHA-256 hardware fingerprint required; no random fallback");break;}
  if(value.isEmpty())throw new IllegalArgumentException("Set YN_BINDING_VALUE");binding=JSON.createObjectNode().put("type",KIND).put("value",value);bindingHash=sha(bytes(KIND+"\0"+(KIND.equals("seat")?publicHash:value)));
 }
 static long trustedTime(ObjectNode cache){long now=Instant.now().getEpochSecond(),high=cache.path("highwater").asLong();if(now+120<high)throw new SecurityException("Clock moved backwards; online validation required");return Math.max(now,high);}
 static JWKSet keys(boolean force)throws Exception{Path cached=STATE.resolve("jwks.json");if(!force&&Files.exists(cached))return JWKSet.parse(Files.readString(cached));HttpResponse<String> response=HTTP.send(HttpRequest.newBuilder(URI.create(BASE+"/v2/applications/"+APP_ID+"/.well-known/jwks.json")).timeout(Duration.ofSeconds(10)).GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new SecurityException("JWKS endpoint refused");JsonNode data=JSON.readTree(response.body());save("jwks.json",data);return JWKSet.parse(response.body());}
 // Optional pinned PEM loading, using the standard JDK SPKI parser.
 static PublicKey loadPublicPEM(String pem)throws Exception{String b64=pem.replace("-----BEGIN PUBLIC KEY-----","").replace("-----END PUBLIC KEY-----","").replaceAll("\\s","");return KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(b64)));}
 static final class Expired extends SecurityException{}
 static JWTClaimsSet localVerify(String token,String purpose,String activation,ObjectNode cache)throws Exception{
  SignedJWT signed=SignedJWT.parse(token);JWSHeader h=signed.getHeader();if(!JWSAlgorithm.RS256.equals(h.getAlgorithm())||h.getKeyID()==null||!h.getKeyID().startsWith(APP_ID+".v"))throw new SecurityException("Untrusted algorithm or application key");JWK jwk=keys(false).getKeyByKeyId(h.getKeyID());if(jwk==null)jwk=keys(true).getKeyByKeyId(h.getKeyID());if(!(jwk instanceof RSAKey rsa)||rsa.size()<2048||!signed.verify(new RSASSAVerifier(rsa.toRSAPublicKey())))throw new SecurityException("Invalid JWT signature");JWTClaimsSet c=signed.getJWTClaimsSet();long now=trustedTime(cache);
  if(c.getExpirationTime()==null||c.getIssueTime()==null||c.getNotBeforeTime()==null||c.getSubject()==null||c.getJWTID()==null||!APP_ID.equals(c.getAudience().size()==1?c.getAudience().get(0):"")||!ISSUER.equals(c.getIssuer())||!purpose.equals(c.getStringClaim("token_use"))||!activation.equals(c.getStringClaim("activation_id")))throw new SecurityException("JWT scope or required claims invalid");Map<String,Object> b=c.getJSONObjectClaim("binding");if(b==null||!KIND.equals(b.get("type"))||!bindingHash.equals(b.get("hash")))throw new SecurityException("Binding fingerprint mismatch");if(c.getNotBeforeTime().toInstant().getEpochSecond()>now||c.getIssueTime().toInstant().getEpochSecond()>now+120)throw new SecurityException("Token not yet valid");if(now>=c.getExpirationTime().toInstant().getEpochSecond())throw new Expired();return c;
 }
 static final class Refusal extends SecurityException{Refusal(String message){super(message);}}
 static ObjectNode send(String path,ObjectNode payload)throws Exception{byte[] body=JSON.writeValueAsBytes(payload),nonceBytes=new byte[24];new SecureRandom().nextBytes(nonceBytes);String nonce=Base64.getUrlEncoder().withoutPadding().encodeToString(nonceBytes),stamp=Long.toString(Instant.now().getEpochSecond());String message=String.join("\n","YN-AUTH-V2","POST",path,APP_ID,stamp,nonce,sha(body));Signature signer=Signature.getInstance("Ed25519");signer.initSign(privateKey);signer.update(bytes(message));String proof=Base64.getUrlEncoder().withoutPadding().encodeToString(signer.sign());HttpRequest request=HttpRequest.newBuilder(URI.create(BASE+path)).timeout(Duration.ofSeconds(15)).header("Content-Type","application/json").header("X-YN-Timestamp",stamp).header("X-YN-Nonce",nonce).header("X-YN-Signature",proof).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();HttpResponse<String> response=HTTP.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200){discardTokens();throw new Refusal("Authorization server refused: "+response.body());}JsonNode envelope=JSON.readTree(response.body());if(!envelope.path("success").asBoolean()){discardTokens();throw new Refusal("Invalid server response");}return (ObjectNode)envelope.get("data");}
 public static void main(String[] args)throws Exception{initialize();String operation=args.length>0?args[0]:"verify";ObjectNode cache=load("cache.json");trustedTime(cache);if(operation.equals("local")){JWTClaimsSet c=localVerify(cache.path("jwt").asText(),"license",cache.path("activation_id").asText(),cache);System.out.println(JSON.createObjectNode().put("valid",true).put("license_id",c.getSubject()));return;}
  if(cache.hasNonNull("jwt")){try{localVerify(cache.path("jwt").asText(),"license",cache.path("activation_id").asText(),cache);}catch(Expired ignored){}catch(Exception e){discardTokens();cache=load("cache.json");}}
  if(operation.equals("request")){ObjectNode payload=JSON.createObjectNode().put("app_id",APP_ID).put("public_key",publicText);payload.set("binding",binding);System.out.println(send("/v2/installations/request",payload));return;}
  boolean activating=operation.equals("activate")||!cache.hasNonNull("activation_id");ObjectNode payload=JSON.createObjectNode().put("app_id",APP_ID).put("form",FORM);payload.set("binding",binding);String endpoint="/v2/verify";if(activating){endpoint="/v2/activate";payload.put("public_key",publicText);if(!env("YN_BORROW_SECONDS","").isEmpty())payload.put("borrow_seconds",Integer.parseInt(env("YN_BORROW_SECONDS","0")));if(!env("YN_CARD","").isEmpty())payload.put("card_code",env("YN_CARD",""));else if(!env("YN_INVITATION_ID","").isEmpty()){payload.put("invitation_id",env("YN_INVITATION_ID","")).put("invitation_token",env("YN_INVITATION_TOKEN",""));}else payload.put("pending_id",env("YN_PENDING_ID",""));}else{payload.put("activation_id",cache.path("activation_id").asText());if(List.of("release","consume","renew").contains(operation))payload.put("action",operation);if(operation.equals("consume"))payload.put("units",Long.parseLong(env("YN_UNITS","1"))).put("idempotency_key",env("YN_OPERATION_ID",""));if(operation.equals("renew"))payload.put("renewal_card",env("YN_RENEWAL_CARD",""));}
  ObjectNode result;try{result=send(endpoint,payload);}catch(IOException e){boolean network=e instanceof java.net.ConnectException || e instanceof java.net.http.HttpTimeoutException || e instanceof java.net.SocketException || e instanceof java.net.UnknownHostException;if(!network || e instanceof javax.net.ssl.SSLException)throw e;if(activating||!operation.equals("verify")||!cache.hasNonNull("offline_jwt"))throw e;JWTClaimsSet c=localVerify(cache.path("offline_jwt").asText(),"offline_grace",cache.path("activation_id").asText(),cache);cache.put("highwater",trustedTime(cache));save("cache.json",cache);System.out.println(JSON.createObjectNode().put("valid",true).put("offline",true).put("grace_until",c.getExpirationTime().toInstant().getEpochSecond()));return;}
  if(result.path("released").asBoolean()){discardTokens();System.out.println("{\"released\":true}");return;}localVerify(result.path("jwt").asText(),"license",result.path("activation_id").asText(),JSON.createObjectNode());result.put("highwater",Math.max(Instant.now().getEpochSecond(),Instant.parse(result.path("server_time").asText()).getEpochSecond()));save("cache.json",result);System.out.println(JSON.createObjectNode().put("valid",true).put("license_id",result.path("license_id").asText()).put("activation_id",result.path("activation_id").asText()));
 }
}
